import os
import re
import numpy as np


def parse_match_file_flexible(path):
    """Flexibly parse pred_zmat_match.txt to extract matching information."""
    with open(path, 'r') as <local-path>        content = f.read()
    lines = content.splitlines()

    orig_indices = []
    matched_indices = []

    # Try format 1: "Original indices: [1, 2, 3, ...]" and "Matched indices: [1, 2, 3, ...]"
    orig_match = re.search(r'[Oo]riginal\s+[Ii]ndices\s*:\s*\[([^\]]+)\]', content)
    matched_match = re.search(r'[Mm]atched\s+[Ii]ndices\s*:\s*\[([^\]]+)\]', content)

    if orig_match and matched_match:
        orig_indices = [int(x.strip()) for x in orig_match.group(1).split(',')]
        matched_indices = [int(x.strip()) for x in matched_match.group(1).split(',')]
        return orig_indices, matched_indices

    # Try format 2: per-line "Original Index: N, Matched Index: M"
    for line in lines:
        m = re.search(r'[Oo]riginal\s+[Ii]ndex\s*:\s*(\d+)\s*,\s*[Mm]atched\s+[Ii]ndex\s*:\s*(-?\d+)', line)
        if <local-path>            orig_indices.append(int(m.group(1)))
            matched_indices.append(int(m.group(2)))
    if orig_indices:
        return orig_indices, matched_indices

    # Try format 3: "orig_idx -> matched_idx" or "N -> M"
    for line in lines:
        m = re.search(r'(\d+)\s*[-=]>\s*(-?\d+)', line)
        if <local-path>            orig_indices.append(int(m.group(1)))
            matched_indices.append(int(m.group(2)))
    if orig_indices:
        return orig_indices, matched_indices

    # Try format 4: lines with at least two integers (first two are orig and matched)
    for line in lines:
        parts = line.split()
        nums = []
        for p in parts:
            try:
                nums.append(int(p))
            except ValueError:
                pass
        if len(nums) >= 2:
            orig_indices.append(nums[0])
            matched_indices.append(nums[1])

    return orig_indices, matched_indices


def parse_poscar(path):
    """Parse VASP POSCAR file to extract cell and positions."""
    with open(path, 'r') as <local-path>        lines = [l.rstrip() for l in f.readlines()]

    scale = float(lines[1].strip())
    cell = []
    for i in range(2, 5):
        cell.append([float(x) * scale for x in lines[i].split()])
    cell = np.array(cell)

    idx = 5
    # Try to detect species line vs count line
    try:
        counts = [int(x) for x in lines[idx].split()]
        natom = sum(counts)
        idx += 1
    except ValueError:
        # species line
        idx += 1
        counts = [int(x) for x in lines[idx].split()]
        natom = sum(counts)
        idx += 1

    # Check for selective dynamics
    if lines[idx].strip().lower().startswith('s'):
        idx += 1

    coord_type = lines[idx].strip()
    idx += 1

    positions = []
    for i in range(natom):
        if idx + i < len(lines) and lines[idx + i].strip():
            parts = lines[idx + i].split()
            if len(parts) >= 3:
                positions.append([float(x) for x in parts[:3]])
    positions = np.array(positions)

    return cell, positions, natom, coord_type


def check_zmat_file(path, expected_natoms):
    """
    Flexibly check zmat_output.txt.
    Accepts any format that contains structural information for roughly the right number of atoms.
    """
    with open(path, 'r') as <local-path>        content = f.read()
    lines = [l.strip() for l in content.splitlines() if l.strip() and not l.strip().startswith('#')]

    if len(lines) == 0:
        return False, "Z-matrix file is empty"

    # Count non-empty lines as a proxy for atom entries
    # Accept if we have at least 50% of expected atoms represented
    if len(lines) < expected_natoms * 0.5:
        return False, f"Z-matrix has too few lines: {len(lines)} vs expected ~{expected_natoms}"

    # Check that file contains numeric data (bond lengths, angles, etc.)
    has_numbers = False
    for line in lines[:min(10, len(lines))]:
        if re.search(r'\d+\.\d+', line):
            has_numbers = True
            break

    if not has_numbers:
        return False, "Z-matrix file doesn't appear to contain numeric structural data"

    return True, f"Z-matrix has {len(lines)} entries"


def get_trajectory_info(traj_file):
    """Get basic info about the trajectory."""
    try:
        from ase import io
        traj = io.read(traj_file, index=':')
        if traj:
            structure = traj[-1]  # Use last frame (default read behavior)
            return {
                'natoms': len(structure),
                'symbols': structure.get_chemical_symbols(),
                'positions': structure.get_positions(),
                'cell': structure.get_cell().array
            }
    except Exception as <local-path>        return None


def eval():
    pred_dir = 'pred_results'
    traj_file = 'benchmark/datasets/I-ReaxFF/test/md.traj'

    # Step 1: Check file existence
    required_files = ['pred_zmat_match.txt', 'zmat_output.txt', 'POSCAR.mat']
    for fname in required_files:
        pred_path = os.path.join(pred_dir, fname)
        if not os.path.exists(pred_path):
            return (False, f"Missing predicted file: {fname}")
        if os.path.getsize(pred_path) == 0:
            return (False, f"Predicted file is empty: {fname}")

    # Get ground truth from trajectory
    traj_info = get_trajectory_info(traj_file)
    if traj_info is None:
        return (False, f"Could not read trajectory file: {traj_file}")

    expected_natoms = traj_info['natoms']
    expected_symbols = traj_info['symbols']

    # Step 2: Validate matching results file
    try:
        pred_orig, pred_matched = parse_match_file_flexible(
            os.path.join(pred_dir, 'pred_zmat_match.txt'))
    except Exception as <local-path>        return (False, f"Failed to parse pred_zmat_match.txt: {e}")

    if not pred_orig or not pred_matched:
        return (False, "Could not parse any matching indices from pred_zmat_match.txt")

    # Check we have the right number of atoms
    if len(pred_orig) != expected_natoms:
        return (False, f"Number of matched atoms ({len(pred_orig)}) doesn't match "
                f"expected ({expected_natoms})")

    if len(pred_matched) != expected_natoms:
        return (False, f"Number of matched indices ({len(pred_matched)}) doesn't match "
                f"expected ({expected_natoms})")

    # For self-matching (ref == target), verify the matching produces a valid permutation
    # The matched indices should be a valid permutation of 0..N-1
    valid_matched = [m for m in pred_matched if 0 <= m < expected_natoms]
    matched_set = set(valid_matched)

    # Require at least 90% unique matches (valid permutation)
    if len(matched_set) < expected_natoms * 0.9:
        return (False, f"Matching doesn't form a valid permutation: only {len(matched_set)} "
                f"unique matched indices out of {expected_natoms}. "
                f"Z-matrix matching requires a bijective mapping between atoms.")

    # Check that matched atoms preserve chemical symbols
    symbol_correct = 0
    for orig_i, matched_i in zip(pred_orig, pred_matched):
        if 0 <= matched_i < expected_natoms:
            if expected_symbols[orig_i] == expected_symbols[matched_i]:
                symbol_correct += 1

    symbol_match_rate = symbol_correct / expected_natoms
    if symbol_match_rate < 0.9:
        return (False, f"Chemical symbol preservation too low: {symbol_match_rate:.2%} "
                f"(threshold: 90%). Matched atoms must have the same chemical symbol.")

    # Step 3: Verify POSCAR structural preservation
    try:
        pred_cell, pred_pos, pred_natom, pred_coord = parse_poscar(
            os.path.join(pred_dir, 'POSCAR.mat'))
    except Exception as <local-path>        return (False, f"Failed to parse POSCAR.mat: {e}")

    if pred_natom != expected_natoms:
        return (False, f"POSCAR atom count mismatch: {pred_natom} vs expected {expected_natoms}")

    # Convert positions to Cartesian if needed
    if pred_coord.lower().startswith('d'):
        pred_pos_cart = pred_pos @ pred_cell
    else:
        pred_pos_cart = pred_pos

    # Check that the set of positions matches (allowing for reordering)
    # Since this is self-matching, all original positions should be present
    orig_positions = traj_info['positions']

    pos_tolerance = 0.1  # Angstroms
    matched_pos_count = 0
    for pos in pred_pos_cart:
        dists = np.linalg.norm(orig_positions - pos, axis=1)
        if np.min(dists) < pos_tolerance:
            matched_pos_count += 1

    pos_match_rate = matched_pos_count / expected_natoms
    if pos_match_rate < 0.9:
        return (False, f"POSCAR positions don't match original structure: "
                f"only {pos_match_rate:.2%} positions matched (tolerance: {pos_tolerance} Ã)")

    # Step 4: Validate Z-matrix output (flexible format check)
    try:
        zmat_ok, zmat_msg = check_zmat_file(
            os.path.join(pred_dir, 'zmat_output.txt'), expected_natoms)
    except Exception as <local-path>        return (False, f"Failed to read zmat_output.txt: {e}")

    if not zmat_ok:
        return (False, f"Z-matrix validation failed: {zmat_msg}")

    return (True, f"All checks passed: "
            f"{len(pred_orig)} atoms matched with {symbol_match_rate:.1%} symbol preservation, "
            f"POSCAR has {pred_natom} atoms with {pos_match_rate:.1%} position match, "
            f"{zmat_msg}")


if __name__ == '__main__':
    result, reason = eval()
    print(f"Result: {'PASS' if result else 'FAIL'}")
    print(f"Reason: {reason}")

import os
import numpy as np
import json


PRED_DIR = "pred_results"
GOLD_DIR = "./gold_results"

REQUIRED_FILES = [
    "pred_pltp_vdwtaper.pdf",
    "pred_pltp_vdwtaper.txt",
    "pred_pltp_f13.pdf",
    "pred_pltp_f13.txt",
]


def parse_txt_first_two_cols(filepath):
    """Parse a comma-separated text file, returning first two columns, skipping comment lines."""
    radii = []
    values = []
    with open(filepath, "r") as <local-path>        for line in <local-path>            line = line.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split(",")
            if len(parts) < 2:
                continue
            try:
                radii.append(float(parts[0].strip()))
                values.append(float(parts[1].strip()))
            except ValueError:
                continue
    return np.array(radii), np.array(values)


def parse_txt_all_cols(filepath):
    """Parse a comma-separated text file, returning all columns."""
    rows = []
    with open(filepath, "r") as <local-path>        for line in <local-path>            line = line.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split(",")
            if len(parts) < 2:
                continue
            try:
                row = [float(p.strip()) for p in parts]
                rows.append(row)
            except ValueError:
                continue
    if not rows:
        return np.array([])
    return np.array(rows)


def check_uses_ffield_params(ffield_path):
    """Check that ffield.json exists and is readable."""
    try:
        with open(ffield_path, 'r') as <local-path>            data = json.load(f)
        return True, data
    except Exception as <local-path>        return False, str(e)


def eval():
    # 1. Check all required files exist and are non-empty
    for fname in REQUIRED_FILES:
        pred_path = os.path.join(PRED_DIR, fname)
        if not os.path.exists(pred_path):
            return False, f"Missing predicted file: {fname}"
        if os.path.getsize(pred_path) == 0:
            return False, f"Predicted file is empty: {fname}"

    # 2. Check ffield.json is accessible (solution should use it)
    ffield_path = "benchmark/datasets/I-ReaxFF/test/ffield.json"
    ffield_ok, ffield_data = check_uses_ffield_params(ffield_path)
    if not ffield_ok:
        return False, f"Could not read ffield.json: {ffield_data}"

    # 3. Validate vdwtaper text data structure and basic properties
    try:
        pred_r_tap, pred_v_tap = parse_txt_first_two_cols(
            os.path.join(PRED_DIR, "pred_pltp_vdwtaper.txt")
        )
    except Exception as <local-path>        return False, f"Error parsing vdwtaper txt file: {e}"

    if len(pred_r_tap) < 50:
        return False, f"Taper data has too few points: {len(pred_r_tap)} (need >=50)"

    # Check radius range coverage (flexible: just needs to cover most of [0.2, 10.0])
    if pred_r_tap[0] > 0.5:
        return False, (
            f"Taper radius range should start near 0.2, got {pred_r_tap[0]:.3f}"
        )
    if pred_r_tap[-1] < 9.0:
        return False, (
            f"Taper radius range should end near 10.0, got {pred_r_tap[-1]:.3f}"
        )

    # Check for NaN/Inf
    if np.any(np.isnan(pred_v_tap)) or np.any(np.isinf(pred_v_tap)):
        return False, "Taper function contains NaN or Inf values"

    # Check physical reasonableness of taper function:
    # - Should be bounded (values between -0.1 and 1.1)
    if np.any(pred_v_tap > 1.1) or np.any(pred_v_tap < -0.1):
        return False, (
            f"Taper function values out of reasonable range [0,1]: "
            f"min={pred_v_tap.min():.4f}, max={pred_v_tap.max():.4f}"
        )

    # Check that taper function is not constant
    value_range = pred_v_tap.max() - pred_v_tap.min()
    if value_range < 0.01:
        return False, (
            f"Taper function appears constant (range={value_range:.4f}); "
            f"should vary with radius"
        )

    # Check that taper function starts near 1.0 at small radii
    # (at r=0.2, well within cutoff, taper should be ~1)
    small_r_mask = pred_r_tap <= 1.0
    if np.any(small_r_mask):
        small_r_vals = pred_v_tap[small_r_mask]
        if np.mean(small_r_vals) < 0.5:
            return False, (
                f"Taper function should be ~1.0 at small radii, "
                f"got mean={np.mean(small_r_vals):.3f} for r<=1.0"
            )

    # Check that taper function ends near 0.0 at large radii (r >= r_off)
    # The cutoff is typically around 10.0 Angstroms
    large_r_mask = pred_r_tap >= 9.9
    if np.any(large_r_mask):
        large_r_vals = pred_v_tap[large_r_mask]
        if np.mean(large_r_vals) > 0.5:
            return False, (
                f"Taper function should approach 0.0 at large radii (>=10.0), "
                f"got mean={np.mean(large_r_vals):.3f}"
            )

    # Check that taper is generally monotonically non-increasing (with some tolerance)
    # Allow for small numerical noise
    sorted_idx = np.argsort(pred_r_tap)
    sorted_r = pred_r_tap[sorted_idx]
    sorted_v = pred_v_tap[sorted_idx]
    # Check that the taper doesn't increase significantly after it starts decreasing
    max_val = sorted_v[0]
    max_increase = 0.0
    current_min = sorted_v[0]
    for v in sorted_v[1:]:
        if v < current_min:
            current_min = v
        elif v - current_min > max_increase:
            max_increase = v - current_min
    if max_increase > 0.1:
        return False, (
            f"Taper function is not monotonically non-increasing "
            f"(max increase after decrease = {max_increase:.4f})"
        )

    # 4. Validate f13 text data structure and basic properties
    try:
        f13_all = parse_txt_all_cols(os.path.join(PRED_DIR, "pred_pltp_f13.txt"))
    except Exception as <local-path>        return False, f"Error parsing f13 txt file: {e}"

    if len(f13_all) < 50:
        return False, f"f13 data has too few points: {len(f13_all)} (need >=50)"

    if f13_all.shape[1] < 2:
        return False, f"f13 file should have at least 2 columns (radius + values)"

    pred_r_f13 = f13_all[:, 0]
    pred_v_f13 = f13_all[:, 1]  # Use first function column for basic checks

    # Check radius range coverage
    if pred_r_f13[0] > 0.1:
        return False, (
            f"f13 radius range should start near 0.01, got {pred_r_f13[0]:.3f}"
        )
    if pred_r_f13[-1] < 2.5:
        return False, (
            f"f13 radius range should end near 3.0, got {pred_r_f13[-1]:.3f}"
        )

    # Check for NaN/Inf in all columns
    if np.any(np.isnan(f13_all)) or np.any(np.isinf(f13_all)):
        return False, "f13 function contains NaN or Inf values"

    # Check f13 varies with radius (not constant) - check first function column
    f13_range = pred_v_f13.max() - pred_v_f13.min()
    if f13_range < 0.01:
        return False, (
            f"f13 function appears constant (range={f13_range:.4f}); "
            f"should vary with radius"
        )

    # Check that f13 has reasonable values (should be positive, typically [0, ~1])
    if np.any(pred_v_f13 < -0.01):
        return False, (
            f"f13 function has negative values: min={pred_v_f13.min():.4f}. "
            f"f13 should be non-negative."
        )

    # Check that f13 uses gamma parameters from ffield.json
    # The f13 function should depend on gamma parameters
    # We verify that multiple atom types produce different curves (if multiple columns)
    if f13_all.shape[1] >= 3:
        # Multiple gamma values should produce different f13 curves
        col1 = f13_all[:, 1]
        col2 = f13_all[:, 2]
        diff = np.abs(col1 - col2).max()
        # If all gamma values are identical, curves might be the same - that's OK
        # Just check that they're all reasonable
        for col_idx in range(1, f13_all.shape[1]):
            col_vals = f13_all[:, col_idx]
            if np.any(col_vals < -0.01) or np.any(col_vals > 1.1):
                return False, (
                    f"f13 column {col_idx} has values outside reasonable range [0,1]: "
                    f"min={col_vals.min():.4f}, max={col_vals.max():.4f}"
                )

    # Check that f13 uses gamma from ffield.json
    # Extract gamma values and verify f13 is consistent with exp(-gamma * r^2) form
    # This is a soft check - verify at least one gamma value gives reasonable fit
    try:
        gammas_dict = {k: v for k, v in ffield_data['p'].items() if k.startswith('gammaw_')}
        if gammas_dict:
            gamma_vals = list(gammas_dict.values())
            # Check if any gamma value gives a reasonable fit to first f13 column
            # f13 = exp(-gamma * r^2) is a common form
            r = pred_r_f13
            best_rmse = float('inf')
            for gamma in gamma_vals:
                expected = np.exp(-gamma * r**2)
                rmse = np.sqrt(np.mean((pred_v_f13 - expected)**2))
                if rmse < best_rmse:
                    best_rmse = rmse
            # Very loose check - just verify f13 is related to gamma parameters
            # If best RMSE is very large, the formula might be completely wrong
            # But we allow flexibility in exact formula
            if best_rmse > 1.0:
                # Try alternative: f13 = 1/(1 + exp(-gamma*r)) etc.
                # Just warn, don't fail - the formula might be valid
                pass
    except Exception:
        pass  # Don't fail on this check

    # 5. Check PDF files have reasonable size
    for pdf_fname in ["pred_pltp_vdwtaper.pdf", "pred_pltp_f13.pdf"]:
        pdf_path = os.path.join(PRED_DIR, pdf_fname)
        pdf_size = os.path.getsize(pdf_path)
        if pdf_size < 1000:  # PDF should be at least 1KB
            return False, f"PDF file seems too small ({pdf_size} bytes): {pdf_fname}"

    # 6. Optional: loose comparison with gold files (informational only, no failure)
    gold_comparison_info = ""
    gold_tap_path = os.path.join(GOLD_DIR, "pred_pltp_vdwtaper.txt")
    gold_f13_path = os.path.join(GOLD_DIR, "pred_pltp_f13.txt")

    if os.path.exists(gold_tap_path) and os.path.exists(gold_f13_path):
        try:
            gold_r_tap, gold_v_tap = parse_txt_first_two_cols(gold_tap_path)
            gold_r_f13, gold_v_f13 = parse_txt_first_two_cols(gold_f13_path)

            if len(gold_r_tap) >= 50 and len(gold_r_f13) >= 50:
                # Interpolate to common grid
                common_r_tap = np.linspace(
                    max(pred_r_tap[0], gold_r_tap[0]),
                    min(pred_r_tap[-1], gold_r_tap[-1]),
                    200
                )
                pred_interp_tap = np.interp(common_r_tap, pred_r_tap, pred_v_tap)
                gold_interp_tap = np.interp(common_r_tap, gold_r_tap, gold_v_tap)
                rmse_tap = np.sqrt(np.mean((pred_interp_tap - gold_interp_tap) ** 2))

                common_r_f13 = np.linspace(
                    max(pred_r_f13[0], gold_r_f13[0]),
                    min(pred_r_f13[-1], gold_r_f13[-1]),
                    200
                )
                pred_interp_f13 = np.interp(common_r_f13, pred_r_f13, pred_v_f13)
                gold_interp_f13 = np.interp(common_r_f13, gold_r_f13, gold_v_f13)
                rmse_f13 = np.sqrt(np.mean((pred_interp_f13 - gold_interp_f13) ** 2))

                gold_comparison_info = (
                    f", Taper RMSE vs gold={rmse_tap:.2e}, "
                    f"f13 RMSE vs gold={rmse_f13:.2e}"
                )
                # Note: We do NOT fail based on gold comparison because multiple
                # valid taper formulations exist in the literature
        except Exception as <local-path>            gold_comparison_info = f" (gold comparison failed: {e})"

    return True, (
        f"All checks passed. 4 required files present, data ranges verified, "
        f"physical behavior reasonable{gold_comparison_info}."
    )


if __name__ == "__main__":
    passed, reason = eval()
    print(f"{'PASS' if passed else 'FAIL'}: {reason}")

