import json
import numpy as np
import os
import re


def eval():
    pred_json_path = "pred_results/pred_nn.json"
    pred_txt_path = "pred_results/pred_nn.txt"

    # Step 1: Check file existence
    if not os.path.exists(pred_json_path):
        return (False, f"Missing predicted output file: {pred_json_path}")
    if not os.path.exists(pred_txt_path):
        return (False, f"Missing predicted output file: {pred_txt_path}")

    # Step 2: Load JSON file
    try:
        with open(pred_json_path, 'r') as <local-path>            pred = json.load(f)
    except (json.JSONDecodeError, Exception) as <local-path>        return (False, f"Failed to parse predicted JSON: {e}")

