import os
import numpy as np
import xml.etree.ElementTree as ET


def eval():
    pred_dir = "pred_results"
    gold_dir = "./gold_results/"

    pred_svg = os.path.join(pred_dir, "pred_plot_zmat_pes.svg")
    pred_txt = os.path.join(pred_dir, "pred_plot_zmat_pes.txt")
    pred_surface = os.path.join(pred_dir, "pred_plot_zmat_pes_surface.txt")

    gold_txt = os.path.join(gold_dir, "pred_plot_zmat_pes.txt")
    gold_surface = os.path.join(gold_dir, "pred_plot_zmat_pes_surface.txt")

    # Step 1: Verify file existence
    for fpath, label in [(pred_svg, "SVG plot"), (pred_txt, "trajectory data"),
                         (pred_surface, "surface data")]:
        if not os.path.exists(fpath):
            return (False, f"Missing predicted file: {label} ({fpath})")

    # Check SVG file size > 5 KB (relaxed from 10 KB)
    svg_size = os.path.getsize(pred_svg)
    if svg_size < 5000:
        return (False, f"SVG file too small ({svg_size} bytes), likely empty or incomplete plot")

    # Validate SVG is valid XML
    try:
        ET.parse(pred_svg)
    except ET.ParseError as <local-path>        return (False, f"SVG file is not valid XML: {e}")

    # Step 2: Load and validate data files
    def load_data(filepath):
        """Load whitespace-separated numeric data, skipping comment lines."""
        rows = []
        with open(filepath, 'r') as <local-path>            for line in <local-path>                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                parts = line.split()
                try:
                    rows.append([float(x) for x in parts])
                except ValueError:
                    continue
        return np.array(rows) if rows else np.array([]).reshape(0, 0)

    try:
        pred_traj = load_data(pred_txt)
    except Exception as <local-path>        return (False, f"Failed to parse predicted trajectory file: {e}")

    try:
        pred_surf = load_data(pred_surface)
    except Exception as <local-path>        return (False, f"Failed to parse predicted surface file: {e}")

    # Validate column counts
    if pred_traj.ndim != 2 or pred_traj.shape[1] < 4:
        return (False, f"Trajectory file should have at least 4 columns, got shape {pred_traj.shape}")

    if pred_surf.ndim != 2 or pred_surf.shape[1] < 3:
        return (False, f"Surface file should have at least 3 columns, got shape {pred_surf.shape}")

    # Step 2b: Data completeness - require >= 100 grid points
    if pred_traj.shape[0] < 100:
        return (False, f"Trajectory has only {pred_traj.shape[0]} points, need >= 100")

    if pred_surf.shape[0] < 100:
        return (False, f"Surface has only {pred_surf.shape[0]} points, need >= 100")

    # Step 3: Physical validity checks
    traj_col0 = pred_traj[:, 0]  # distance column 1 (H-O or H-C)
    traj_col1 = pred_traj[:, 1]  # distance column 2 (O-C or C-O)
    traj_energies_dft = pred_traj[:, 2]   # DFT energy
    traj_energies_reax = pred_traj[:, 3]  # ReaxFF energy
    surf_energies = pred_surf[:, 2]

    all_energies = np.concatenate([traj_energies_dft, traj_energies_reax, surf_energies])
    if not np.all(np.isfinite(all_energies)):
        n_bad = np.sum(~np.isfinite(all_energies))
        return (False, f"Found {n_bad} non-finite energy values (NaN or Inf)")

    # Energy range check: allow wide range
    energy_min = np.min(all_energies)
    energy_max = np.max(all_energies)
    if energy_min < -10000 or energy_max > 10000:
        return (False, f"Energy values out of reasonable range: [{energy_min:.2f}, {energy_max:.2f}]")

    # Check distance ranges (columns 0 and 1 of trajectory)
    if np.min(traj_col0) < 0.3 or np.max(traj_col0) > 5.0:
        return (False, f"First distance column out of range: [{np.min(traj_col0):.3f}, {np.max(traj_col0):.3f}]")
    if np.min(traj_col1) < 0.3 or np.max(traj_col1) > 5.0:
        return (False, f"Second distance column out of range: [{np.min(traj_col1):.3f}, {np.max(traj_col1):.3f}]")

    # Step 4: Surface data distance range checks
    surf_r1 = pred_surf[:, 0]
    surf_r2 = pred_surf[:, 1]
    # The surface should cover the H-C range [0.8, 1.4] and C-O range [1.0, 1.5]
    if np.min(surf_r1) < 0.3 or np.max(surf_r1) > 3.0:
        return (False, f"Surface first distance out of range: [{np.min(surf_r1):.3f}, {np.max(surf_r1):.3f}]")
    if np.min(surf_r2) < 0.3 or np.max(surf_r2) > 3.0:
        return (False, f"Surface second distance out of range: [{np.min(surf_r2):.3f}, {np.max(surf_r2):.3f}]")

    # Step 5: DFT-ReaxFF correlation check
    # The task says DFT = ReaxFF + small Gaussian noise
    # So they should be highly correlated. However, we allow some flexibility
    # in case the solution uses a slightly different approach.
    # Check correlation between DFT and ReaxFF energies
    std_dft = np.std(traj_energies_dft)
    std_reax = np.std(traj_energies_reax)

    if std_dft < 1e-10 or std_reax < 1e-10:
        return (False, "Energy columns have near-zero variance, likely constant values")

    r_squared = np.corrcoef(traj_energies_dft, traj_energies_reax)[0, 1] ** 2

    # The task explicitly says DFT = ReaxFF + small noise, so RÂ² should be high
    # But we allow lower threshold to account for different implementations
    # The key requirement is that DFT and ReaxFF are meaningfully correlated
    if r_squared < 0.5:
        return (False, f"DFT-ReaxFF R^2 = {r_squared:.4f}, required >= 0.5 (DFT should be correlated with ReaxFF)")

    # Check that the noise is not too large relative to the energy range
    noise = traj_energies_dft - traj_energies_reax
    noise_std = np.std(noise)
    energy_range = np.max(traj_energies_reax) - np.min(traj_energies_reax)

    # If energy range is very small, the noise check is less meaningful
    if energy_range > 1e-6:
        noise_fraction = noise_std / energy_range
        # Allow noise up to 50% of energy range (very generous)
        if noise_fraction > 0.5:
            return (False, f"DFT noise std ({noise_std:.4f}) is too large relative to energy range ({energy_range:.4f}), ratio={noise_fraction:.3f}")

    # Step 6: Check surface energy variation (should show a meaningful PES, not flat)
    surf_energy_range = np.max(surf_energies) - np.min(surf_energies)
    if surf_energy_range < 1e-10:
        return (False, f"Surface energies are constant ({surf_energies[0]:.4f}), no PES variation")

    # Step 7: Compare against gold standard if available
    gold_comparison_info = ""
    if os.path.exists(gold_txt) and os.path.exists(gold_surface):
        try:
            gold_traj = load_data(gold_txt)
            gold_surf = load_data(gold_surface)

            if gold_surf.ndim == 2 and gold_surf.shape[1] >= 3 and gold_surf.shape[0] >= 100:
                gold_surf_energies = gold_surf[:, 2]
                gold_surf_energy_range = np.max(gold_surf_energies) - np.min(gold_surf_energies)

                if gold_surf_energy_range > 0:
                    range_ratio = surf_energy_range / gold_surf_energy_range
                    # Very lenient: allow energy ranges from 1% to 100x of gold
                    if range_ratio < 0.01 or range_ratio > 100.0:
                        return (False, f"Energy range ratio pred/gold = {range_ratio:.4f}, seems unreasonable")
                    gold_comparison_info = f", gold_range_ratio={range_ratio:.3f}"

                # Check grid size ratio
                size_ratio = pred_surf.shape[0] / gold_surf.shape[0]
                if size_ratio < 0.1 or size_ratio > 10.0:
                    return (False, f"Surface grid size very different: pred={pred_surf.shape[0]}, gold={gold_surf.shape[0]}")

        except Exception as <local-path>            # Gold comparison is optional - don't fail if it errors
            gold_comparison_info = f", gold_comparison_skipped({e})"

    # Step 8: Verify SVG contains a 3D plot (check for typical 3D plot elements)
    try:
        tree = ET.parse(pred_svg)
        root = tree.getroot()
        svg_str = ET.tostring(root, encoding='unicode')
        # SVG should have substantial content (paths, etc.)
        if len(svg_str) < 5000:
            return (False, f"SVG content too minimal ({len(svg_str)} chars)")
    except Exception:
        pass  # Already validated above

    return (True, f"All checks passed. Trajectory: {pred_traj.shape[0]} points, "
                  f"Surface: {pred_surf.shape[0]} points, "
                  f"DFT-ReaxFF RÂ²={r_squared:.4f}, "
                  f"noise_std={noise_std:.4f}, "
                  f"energy_range={surf_energy_range:.4f}, "
                  f"SVG size={svg_size} bytes"
                  f"{gold_comparison_info}")


