                    pred_counts = Counter(c for c in pred_formula if c.isalpha())
                    expected_counts = Counter(symbols)
                    # Simplified check - just verify same elements present
                    pred_elements = set(c.upper() for c in pred_formula if c.isupper())
                    expected_elements = set(s.upper() for s in symbols)
                    if pred_elements != expected_elements:
                        return (False, f"Formula element mismatch at frame {i+1}: pred={pred_formula} vs expected elements={expected_elements}")

            # Check energy from trajectory info if available
            if 'energy' in frame.info:
                traj_energy = frame.info['energy']
                # Allow some tolerance for floating point differences
                if abs(pred['energy'] - traj_energy) > 1e-3:
                    return (False, f"Energy mismatch at frame {i+1}: pred={pred['energy']} vs trajectory={traj_energy} eV")
            elif hasattr(frame, 'get_potential_energy'):
                try:
                    calc_energy = frame.get_potential_energy()
                    if abs(pred['energy'] - calc_energy) > 1e-3:
                        return (False, f"Energy mismatch at frame {i+1}: pred={pred['energy']} vs calculator={calc_energy} eV")
                except:
