    return (True, f"All checks passed. Frames={len(pred_rows)}, energies extracted successfully.")


def _parse_csv(path):
    rows = []
    with open(path, 'r') as <local-path>        reader = csv.DictReader(f)
        for row in reader:
            # Normalize column names
            norm = {k.strip().lower().replace(' ', '_'): v.strip() for k, v in row.items()}

            frame = _get_field(norm, ['frame', 'frame_number', 'frame_idx', 'index'])
            energy = _get_field(norm, ['energy_ev', 'energy', 'energy_(ev)', 'energy(ev)'])
            natoms = _get_field(norm, ['natoms', 'n_atoms', 'num_atoms', 'number_of_atoms', 'atoms'])
            formula = _get_field(norm, ['formula', 'molecular_formula', 'chemical_formula'])

            if frame is None:
                raise ValueError(f"Missing frame column. Available: {list(norm.keys())}")
            if energy is None:
                raise ValueError(f"Missing energy column. Available: {list(norm.keys())}")

            try:
                parsed = {
                    'frame': int(float(frame)),
                    'energy': float(energy),
                    'natoms': int(natoms) if natoms is not None else None,
                    'formula': formula if formula is not None else None,
                }
            except ValueError as <local-path>                raise ValueError(f"Failed to parse row values: {e}, row={norm}")

            rows.append(parsed)
    return rows


def _get_field(row, candidates):
    for c in candidates:
        if c in row:
            return row[c]
    return None


