def eval():
    pred_csv = "pred_results/pred_compare_dft.csv"
    pred_png = "pred_results/pred_compare_dft.png"
    gold_csv = "./gold_results/pred_compare_dft.csv"
    gold_png = "./gold_results/pred_compare_dft.png"

    # Step 1: Check file existence
    for f, label in [(pred_csv, "predicted CSV"), (pred_png, "predicted PNG"),
                     (gold_csv, "gold CSV"), (gold_png, "gold PNG")]:
        if not os.path.exists(f):
            return (False, f"Missing {label} file: {f}")

    # Step 2: Check PNG is non-trivial
    if os.path.getsize(pred_png) < 5000:
        return (False, "Predicted PNG file is too small, likely empty or corrupt")

    # Step 3: Load gold CSV
    try:
        gold_rows = _load_csv(gold_csv)
    except Exception as <local-path>        return (False, f"Failed to load gold CSV: {e}")

    # Step 4: Load predicted CSV
    try:
        pred_rows = _load_csv(pred_csv)
    except Exception as <local-path>        return (False, f"Failed to load predicted CSV: {e}")

    # Step 5: Check row counts match
    if len(pred_rows) != len(gold_rows):
        return (False, f"Row count mismatch: predicted {len(pred_rows)} vs gold {len(gold_rows)}")

    # Step 6: Compare values
    dist_tol = 0.01  # Angstroms
    energy_tol = 0.01  # eV

    for i, (pred, gold) in enumerate(zip(pred_rows, gold_rows)):
        # Check frame number
        if pred["Frame"] != gold["Frame"]:
            return (False, f"Frame mismatch at row {i}: predicted {pred['Frame']} vs gold {gold['Frame']}")

        # Check distance
        if abs(pred["Distance"] - gold["Distance"]) > dist_tol:
            return (False, f"Distance mismatch at frame {pred['Frame']}: "
                    f"predicted {pred['Distance']:.6f} vs gold {gold['Distance']:.6f} "
                    f"(tolerance {dist_tol})")

        # Check energy
        if abs(pred["Energy"] - gold["Energy"]) > energy_tol:
            return (False, f"Energy mismatch at frame {pred['Frame']}: "
                    f"predicted {pred['Energy']:.6f} vs gold {gold['Energy']:.6f} "
                    f"(tolerance {energy_tol})")

        # Sanity checks
        if pred["Distance"] <= 0 or pred["Distance"] > 20:
            return (False, f"Unreasonable distance {pred['Distance']} at frame {pred['Frame']}")
        if math.isnan(pred["Distance"]) or math.isnan(pred["Energy"]):
            return (False, f"NaN value found at frame {pred['Frame']}")
        if math.isinf(pred["Distance"]) or math.isinf(pred["Energy"]):
            return (False, f"Infinite value found at frame {pred['Frame']}")

    return (True, f"All {len(pred_rows)} frames match within tolerance "
            f"(distance: {dist_tol} A, energy: {energy_tol} eV)")


def _load_csv(path):
    rows = []
    with open(path, "r") as <local-path>        reader = csv.DictReader(f)
        headers = reader.fieldnames
        required = {"Frame", "Distance", "Energy"}
        if not required.issubset(set(headers)):
            raise ValueError(f"Missing columns. Expected {required}, got {headers}")
        for row in reader:
            rows.append({
                "Frame": int(row["Frame"]),
                "Distance": float(row["Distance"]),
                "Energy": float(row["Energy"]),
            })
    return rows


