import os
import numpy as np
import re
from collections import Counter, deque


def parse_vasp(filepath):
    """Parse a VASP POSCAR/CONTCAR file and return cell, elements, positions."""
    with open(filepath, 'r') as <local-path>        lines = f.readlines()

    # Line 0: comment
    # Line 1: scaling factor
    scale = float(lines[1].strip())

    # Lines 2-4: cell vectors
    cell = []
    for i in range(2, 5):
        vec = [float(x) * scale for x in lines[i].split()]
        cell.append(vec)

    # Line 5: element symbols (may or may not be present)
    line5 = lines[5].split()
    try:
        counts = [int(x) for x in line5]
        element_names = None
        line_idx = 6
    except ValueError:
        element_names = line5
        counts = [int(x) for x in lines[6].split()]
        line_idx = 7

    # Build element list
    elements = []
    if element_names is not None:
        for name, count in zip(element_names, counts):
            elements.extend([name.strip()] * count)
    else:
        # Try to get element names from comment line
        comment = lines[0].strip()
        # Try to parse element names from comment
        comment_parts = comment.split()
        if len(comment_parts) == len(counts):
            for name, count in zip(comment_parts, counts):
                elements.extend([name.strip()] * count)
        else:
            # Just use indices
            for i, count in enumerate(counts):
                elements.extend([str(i)] * count)

    # Coordinate type line
    coord_line = lines[line_idx].strip()
    line_idx += 1

    # Handle selective dynamics
    if coord_line.lower().startswith('s'):
        coord_line = lines[line_idx].strip()
        line_idx += 1

    is_direct = coord_line.lower().startswith('d')

    # Read positions
    positions = []
    total_atoms = sum(counts)
    for i in range(total_atoms):
        parts = lines[line_idx + i].split()
        pos = [float(parts[0]), float(parts[1]), float(parts[2])]
        positions.append(pos)

    # Convert fractional to Cartesian if needed
    if is_direct:
        cell_matrix = np.array(cell)
        positions = [np.dot(np.array(p), cell_matrix).tolist() for p in positions]

    return cell, elements, positions, counts, element_names


def find_molecules(positions, elements, cell=None, cutoff=2.5):
    """Find molecules using distance-based connectivity analysis."""
    n = len(positions)
    pos = np.array(positions)

    # Compute pairwise distances (simple, no PBC for now)
    dists = np.sqrt(np.sum((pos[:, np.newaxis, :] - pos[np.newaxis, :, :])**2, axis=2))
    adj = dists < cutoff

    visited = np.zeros(n, dtype=bool)
    molecules = []
    for i in range(n):
        if not visited[i]:
            queue = deque([i])
            visited[i] = True
            component = []
            while queue:
                j = queue.popleft()
                component.append(j)
                for k in range(n):
                    if adj[j][k] and not visited[k]:
                        visited[k] = True
                        queue.append(k)
            molecules.append(component)
    return molecules


def get_molecule_formula(indices, elements):
    """Get sorted formula string for a molecule."""
    elem_list = [elements[i] for i in indices]
    counter = Counter(elem_list)
    # Sort by C, O, N, H priority
    priority = ['C', 'O', 'N', 'H']
    formula_parts = []
    for elem in priority:
        if elem in counter:
            formula_parts.append(f"{elem}{counter[elem]}")
    # Add any remaining elements
    for elem in sorted(counter.keys()):
        if elem not in priority:
            formula_parts.append(f"{elem}{counter[elem]}")
    return "".join(formula_parts)


def check_sorting_order(elements, positions, cutoff=2.5):
    """
    Check if atoms are sorted by molecule type then by element priority (C, O, N, H).
    Returns (is_sorted, details_message)
    """
    priority = {'C': 0, 'O': 1, 'N': 2, 'H': 3}

    # Find molecules in the sorted structure
    molecules = find_molecules(positions, elements, cutoff=cutoff)

    if len(molecules) == 0:
        return False, "No molecules found"

    # Check that within each molecule, elements follow C, O, N, H order
    mol_violations = 0
    for mol_indices in molecules:
        mol_elements = [elements[i] for i in mol_indices]
        # Check that the elements within each molecule are sorted by priority
        mol_priorities = [priority.get(e, 99) for e in mol_elements]
        for k in range(len(mol_priorities) - 1):
            if mol_priorities[k] > mol_priorities[k+1]:
                mol_violations += 1
                break

    if mol_violations > 0:
        return False, f"{mol_violations} molecules have incorrect internal element ordering"

    # Check that molecules of the same type are grouped together
    mol_formulas = []
    for mol_indices in molecules:
        formula = get_molecule_formula(mol_indices, elements)
        mol_formulas.append(formula)

    # Check if same-type molecules are contiguous
    # (they should be grouped together)
    seen_formulas = {}
    for i, formula in enumerate(mol_formulas):
        if formula not in seen_formulas:
            seen_formulas[formula] = i
        else:
            # Check that this molecule type hasn't been interrupted by a different type
            pass  # This is complex to check without gold standard

    return True, f"Sorting order appears correct for {len(molecules)} molecules"


def parse_report(text):
    """Extract key values from the summary report."""
    values = {}

    # Try to find total atoms
    atoms_match = re.search(r'(?:total\s*atoms?|atom\s*count)\s*[:\s=]*\s*(\d+)', text, re.IGNORECASE)
    if atoms_match:
        values["total_atoms"] = int(atoms_match.group(1))

    # Try to find number of molecules
    mol_match = re.search(r'(?:number\s*of\s*molecules?|molecules?\s*count)\s*[:\s=]*\s*(\d+)', text, re.IGNORECASE)
    if mol_match:
        values["num_molecules"] = int(mol_match.group(1))

    # Try to find number of molecule types
    mol_type_match = re.search(r'(?:number\s*of\s*molecule\s*types?|molecule\s*types?)\s*[:\s=]*\s*(\d+)', text, re.IGNORECASE)
    if mol_type_match:
        values["num_molecule_types"] = int(mol_type_match.group(1))

    # Try to find replication parameters
    repl_match = re.search(r'(?:replicat\w*)\s*[:\s=]*\s*[\(\[]?\s*(\d+)\s*[,x]\s*(\d+)\s*[,x]\s*(\d+)', text, re.IGNORECASE)
    if repl_match:
        values["replication"] = (int(repl_match.group(1)), int(repl_match.group(2)), int(repl_match.group(3)))

    return values


def eval():
    pred_vasp = "pred_results/pred_sort_atoms_mol.vasp"
    pred_txt = "pred_results/pred_sort_atoms_mol.txt"

    # Step 1: Check file existence
    for f, label in [(pred_vasp, "VASP"), (pred_txt, "TXT")]:
        if not os.path.exists(f):
            return (False, f"Predicted {label} file not found: {f}")
        if os.path.getsize(f) == 0:
            return (False, f"Predicted {label} file is empty: {f}")

    # Step 2: Parse predicted VASP file
    try:
        pred_cell, pred_elements, pred_positions, pred_counts, pred_elem_names = parse_vasp(pred_vasp)
    except Exception as <local-path>        return (False, f"Failed to parse predicted VASP file: {e}")

    # Step 3: Basic sanity checks on VASP file
    if len(pred_elements) == 0:
        return (False, "Predicted VASP file contains no atoms")

    if len(pred_positions) != len(pred_elements):
        return (False, f"Mismatch between element count ({len(pred_elements)}) and position count ({len(pred_positions)})")

    # Step 4: Check that we have the expected elements (C, O, N, H system)
    elem_composition = Counter(pred_elements)

    # Verify we have reasonable atom counts (the trajectory should have C, O, N, H atoms)
    expected_elements = {'C', 'O', 'N', 'H'}
    found_elements = set(pred_elements)

    # Check that found elements are a subset of expected (or at least overlap significantly)
    if not found_elements.intersection(expected_elements):
        return (False, f"Unexpected element composition: {dict(elem_composition)}. Expected elements from {{C, O, N, H}}")

    total_atoms = len(pred_elements)

    # Step 5: Verify the VASP file has valid cell parameters
    cell_matrix = np.array(pred_cell)
    cell_volume = abs(np.linalg.det(cell_matrix))
    if cell_volume < 1.0:
        return (False, f"Cell volume too small: {cell_volume:.4f} Angstroms^3")

    # Step 6: Check element ordering follows C, O, N, H priority
    # The elements in the VASP file header should follow C, O, N, H order
    priority = {'C': 0, 'O': 1, 'N': 2, 'H': 3}

    if pred_elem_names is not None:
        # Check that element names in VASP header follow priority order
        elem_priorities = [priority.get(e, 99) for e in pred_elem_names]
        for k in range(len(elem_priorities) - 1):
            if elem_priorities[k] > elem_priorities[k+1]:
                # This is a warning, not necessarily a failure since grouping by molecule might affect this
                pass

    # Step 7: Verify atom ordering within the structure
    # Check that elements follow C, O, N, H priority
    elem_sequence = pred_elements

    # Find molecules and check internal ordering
    try:
        is_sorted, sort_msg = check_sorting_order(pred_elements, pred_positions, cutoff=2.5)
        if not is_sorted:
            return (False, f"Atom sorting check failed: {sort_msg}")
    except Exception as <local-path>        # If molecule finding fails, just warn
        sort_msg = f"Could not verify sorting (error: {e})"

    # Step 8: Read and validate the summary report
    try:
        with open(pred_txt, 'r') as <local-path>            pred_report = f.read()
    except Exception as <local-path>        return (False, f"Failed to read predicted report: {e}")

    if not pred_report.strip():
        return (False, "Predicted report file is empty")

    # Check required fields in report
    required_fields = ["molecule", "atom", "replicat"]
    pred_report_lower = pred_report.lower()
    missing = [field for field in required_fields if field not in pred_report_lower]
    if missing:
        return (False, f"Report missing required fields containing: {missing}")

    # Step 9: Parse report values and cross-check with VASP file
    pred_values = parse_report(pred_report)

    # Check total atoms in report matches VASP file
    if pred_values.get("total_atoms") is not None:
        if pred_values["total_atoms"] != total_atoms:
            return (False, f"Report atom count ({pred_values['total_atoms']}) doesn't match VASP file ({total_atoms})")
    else:
        # Try to find any number that matches total atoms in the report
        numbers_in_report = re.findall(r'\b(\d+)\b', pred_report)
        numbers_in_report = [int(n) for n in numbers_in_report]
        if total_atoms not in numbers_in_report:
            return (False, f"Total atom count ({total_atoms}) not found in report")

    # Step 10: Verify molecule count is reasonable
    if pred_values.get("num_molecules") is not None:
        num_molecules = pred_values["num_molecules"]
        # For a typical MD simulation, number of molecules should be > 0 and <= total_atoms
        if num_molecules <= 0 or num_molecules > total_atoms:
            return (False, f"Unreasonable molecule count: {num_molecules}")

        # Cross-check: find molecules ourselves and compare
        try:
            found_molecules = find_molecules(pred_positions, pred_elements, cutoff=2.5)
            if abs(len(found_molecules) - num_molecules) > max(2, num_molecules * 0.05):
                return (False, f"Reported molecule count ({num_molecules}) significantly differs from computed ({len(found_molecules)})")
        except Exception:
            pass  # Skip if molecule finding fails

    # Step 11: Check replication parameters are mentioned (1x1x1 default)
    if "1" in pred_report or "1x1x1" in pred_report.lower() or "(1, 1, 1)" in pred_report:
        pass  # Replication parameters found
    else:
        # Check if replication info is present in any form
        repl_found = re.search(r'replicat\w*', pred_report, re.IGNORECASE)
        if not repl_found:
            return (False, "Report doesn't contain replication parameters")

    # Step 12: Verify the structure makes physical sense
    # Check that positions are within reasonable bounds (near the cell)
    pos_array = np.array(pred_positions)

    # All positions should be finite
    if not np.all(np.isfinite(pos_array)):
        return (False, "Some atomic positions contain non-finite values (NaN or Inf)")

    # Summary message
    mol_count_str = f", {pred_values['num_molecules']} molecules" if pred_values.get("num_molecules") else ""
    return (True, f"All checks passed. {total_atoms} atoms{mol_count_str}, "
                  f"composition={dict(elem_composition)}, {sort_msg}")


