def basic_smiles_check(smi):
    """Basic SMILES validation without RDKit - check it's a non-empty string."""
    if not isinstance(smi, str) or len(smi.strip()) == 0:
        return False
    # Basic sanity: contains at least one letter (atom symbol)
    if not re.search(r'[A-Za-z]', smi):
        return False
    return True


def find_column(df, possible_names, required=True):
    """Find a column by trying multiple possible names (case-insensitive)."""
    col_lower = {col.lower(): col for col in df.columns}
    for name in possible_names:
        if name.lower() in col_lower:
            return col_lower[name.lower()]
    if required:
        return None
    return None


