                            return (False, f"Per-reaction CSV {fname} missing column: {col}")
            except Exception as <local-path>                return (False, f"Error parsing per-reaction CSV {fname}: {e}")

    # Check that product SMILES are valid (non-empty)
    empty_products = sum(1 for row in rows if not row.get("product", "").strip())
    if empty_products > len(rows) * 0.1:
        return (False, f"Too many empty product SMILES: {empty_products}/{len(rows)}")

    # Compare with gold results if available
    gold_csv = os.path.join("gold_results", "pred_get_reactant_bag_other_reactions.csv")
    if os.path.exists(gold_csv):
        try:
            with open(gold_csv, 'r') as <local-path>                gold_rows = list(csv.DictReader(f))
            if abs(len(rows) - len(gold_rows)) > len(gold_rows) * 0.1:
                return (False, f"Row count significantly differs from gold: got {len(rows)}, expected {len(gold_rows)}")
        except Exception:
            pass

    return (True, f"Main CSV has {len(rows)} reactions across reaction types {sorted(valid_rxn_idxs)}, with valid reactant and product SMILES. {len(expected_reaction_files)} per-reaction files also present.")

