import json
import os
import math
import numpy as np


def eval():
    """
    Evaluate predicted OA ReactDiff molecular diffusion model results.
    This evaluation checks semantic correctness without requiring a gold file.
    """
    pred_path = "pred_results/pred_demo.json"

    # Step 0: Check file exists and is valid JSON
    if not os.path.exists(pred_path):
        return (False, "Predicted output file pred_results/pred_demo.json not found")

    try:
        with open(pred_path, "r") as <local-path>            pred = json.load(f)
    except (json.JSONDecodeError, Exception) as <local-path>        return (False, f"Failed to parse predicted JSON: {e}")

    errors = []
    checks_passed = []

    # Helper function to find a value by multiple possible key names
    def find_key(d, *keys):
        for k in keys:
            if k in <local-path>                return d[k]
        return None

    # Step 1: Check that the output is non-empty
    if not pred:
        return (False, "Predicted JSON is empty")
    checks_passed.append("JSON file exists and is valid")

    # Step 2: Check for RMSD matrix data
    # Accept various key names: rmsd_matrix, rmsd_matrix_data, pairwise_rmsd
    rmsd_matrix = find_key(pred, "rmsd_matrix", "rmsd_matrix_data", "pairwise_rmsd")
    rmsd_shape = find_key(pred, "rmsd_matrix_shape")
    rmsd_mean = find_key(pred, "rmsd_matrix_mean")

    if rmsd_matrix is not None:
        # Validate it's a 2D matrix
        if isinstance(rmsd_matrix, list) and len(rmsd_matrix) > 0:
            n = len(rmsd_matrix)
            if isinstance(rmsd_matrix[0], list) and len(rmsd_matrix[0]) == <local-path>                checks_passed.append(f"RMSD matrix found with shape {n}x{n}")
                # Check it's symmetric (diagonal should be 0)
                matrix = np.array(rmsd_matrix)
                diag_zero = np.allclose(np.diag(matrix), 0, atol=1e-6)
                if not diag_zero:
                    errors.append("RMSD matrix diagonal is not zero (self-RMSD should be 0)")
                else:
                    checks_passed.append("RMSD matrix diagonal is zero (correct)")
                # Check symmetry
                sym_check = np.allclose(matrix, matrix.T, atol=1e-6)
                if not sym_check:
                    errors.append("RMSD matrix is not symmetric")
                else:
                    checks_passed.append("RMSD matrix is symmetric (correct)")
                # Check non-negative values
                if np.any(matrix < -1e-6):
                    errors.append("RMSD matrix contains negative values")
                else:
                    checks_passed.append("RMSD matrix values are non-negative (correct)")
                # Check reasonable size (should match number of opt_ts files)
                if n < 5 or n > 200:
                    errors.append(f"RMSD matrix size {n} seems unreasonable (expected 5-200)")
                else:
                    checks_passed.append(f"RMSD matrix size {n} is reasonable")
            else:
                errors.append("RMSD matrix is not square 2D")
        else:
            errors.append("RMSD matrix is not a valid list")
    elif rmsd_shape is not None:
        # Accept shape representation
        checks_passed.append(f"RMSD matrix shape found: {rmsd_shape}")
    else:
        errors.append("No RMSD matrix data found in output")

    # Step 3: Check clustering analysis
    # Accept: kmeans_clusters, clustering_analysis, cluster_labels, clusters
    cluster_data = find_key(pred, "kmeans_clusters", "clustering_analysis", "cluster_labels", "clusters")

    if cluster_data is not None:
        if isinstance(cluster_data, list):
            # It's cluster labels list
            n_clusters = len(set(cluster_data))
            if n_clusters == 6:
                checks_passed.append(f"K-means clustering produced 6 clusters (correct)")
            elif n_clusters >= 4 and n_clusters <= 8:
                checks_passed.append(f"K-means clustering produced {n_clusters} clusters (acceptable)")
            else:
                errors.append(f"K-means clustering produced {n_clusters} clusters, expected 6")
        elif isinstance(cluster_data, dict):
            # It's a dict with cluster info
            n_clusters_val = find_key(cluster_data, "n_clusters", "num_clusters")
            if n_clusters_val is not None:
                if n_clusters_val == 6:
                    checks_passed.append("Clustering analysis shows 6 clusters (correct)")
                else:
                    errors.append(f"Clustering shows {n_clusters_val} clusters, expected 6")
            else:
                checks_passed.append("Clustering analysis dict found")
    else:
        errors.append("No clustering data found in output")

    # Step 4: Check reference clusters
    ref_clusters = find_key(pred, "reference_clusters", "ref_clusters", "ref_cluster_assignments")
    if ref_clusters is not None:
        if isinstance(ref_clusters, dict) and len(ref_clusters) > 0:
            checks_passed.append(f"Reference clusters found with {len(ref_clusters)} entries")
        else:
            errors.append("Reference clusters is empty or wrong type")
    else:
        errors.append("No reference clusters found in output")

    # Step 5: Check quality metrics
    quality_data = find_key(pred, "quality_stats", "generated_ts_quality", "ts_quality")
    if quality_data is not None:
        checks_passed.append("Generated TS quality data found")
        # Look for RMSD-related data
        rmsd_data = find_key(quality_data, "avg_rmsd_per_cluster", "mean_rmsd", "rmsd_stats")
        if rmsd_data is not None:
            checks_passed.append("RMSD quality statistics found")
        total = find_key(quality_data, "total_samples", "n_entries", "count")
        if total is not None and isinstance(total, (int, float)) and total > 0:
            checks_passed.append(f"Quality data has {total} entries")
    else:
        errors.append("No quality statistics found in output")

    # Step 6: Check barrier analysis
    barrier_data = find_key(pred, "barrier_stats", "barrier_analysis", "barriers")
    if barrier_data is not None:
        checks_passed.append("Barrier analysis data found")
        # Check for barrier values
        fwd = find_key(barrier_data, "avg_barrier_minus", "avg_barrier_forward", 
                       "mean_barrier_forward", "barrier_forward")
        rev = find_key(barrier_data, "avg_barrier_plus", "avg_barrier_reverse",
                       "mean_barrier_reverse", "barrier_reverse")
        if fwd is not None or rev is not None:
            checks_passed.append("Barrier energy data found (forward/reverse)")
        total = find_key(barrier_data, "total_samples", "n_entries", "count")
        if total is not None and isinstance(total, (int, float)) and total > 0:
            checks_passed.append(f"Barrier data has {total} entries")
    else:
        errors.append("No barrier analysis found in output")

    # Step 7: Check Hessian summary
    hessian_data = find_key(pred, "summary_stats", "hessian_summary", "hessian_data")
    if hessian_data is not None:
        checks_passed.append("Hessian summary data found")
        # Check for imaginary frequency data
        imag_freq = find_key(hessian_data, "imag_freq_counts", "n_single_imaginary_freq",
                             "imaginary_frequencies", "imag_freq")
        if imag_freq is not None:
            checks_passed.append("Imaginary frequency data found")
        # Check for force RMS
        force_rms = find_key(hessian_data, "avg_force_rms", "mean_force_rms", "force_rms")
        if force_rms is not None and isinstance(force_rms, (int, float)):
            if force_rms >= 0:
                checks_passed.append(f"Force RMS found: {force_rms:.6f}")
            else:
                errors.append("Force RMS is negative")
    else:
        errors.append("No Hessian summary found in output")

    # Step 8: Check generated reactions analysis
    gen_data = find_key(pred, "generated_reaction_formulas", "generated_reactions",
                        "generated_analysis", "reaction_formulas")
    if gen_data is not None:
        checks_passed.append("Generated reactions data found")
        if isinstance(gen_data, dict) and len(gen_data) > 0:
            checks_passed.append(f"Generated reactions has {len(gen_data)} entries")
    else:
        errors.append("No generated reactions data found in output")

    # Step 9: Check ground truth comparison
    gt_data = find_key(pred, "ground_truth_rmsd", "ground_truth", "gt_comparison",
                       "gen_vs_gt_comparison")
    if gt_data is not None:
        checks_passed.append("Ground truth comparison data found")
        if isinstance(gt_data, list) and len(gt_data) > 0:
            # Check that RMSD values are non-negative
            if all(isinstance(v, (int, float)) and v >= 0 for v in gt_data):
                checks_passed.append(f"Ground truth RMSD values are valid ({len(gt_data)} values)")
            else:
                errors.append("Ground truth RMSD values contain invalid entries")
        elif isinstance(gt_data, dict):
            checks_passed.append("Ground truth comparison dict found")
    else:
        errors.append("No ground truth comparison found in output")

    # Step 10: Check IRC catalog
    irc_data = find_key(pred, "irc_catalog", "irc_structures", "irc_files")
    if irc_data is not None:
        checks_passed.append("IRC catalog data found")
        if isinstance(irc_data, dict) and len(irc_data) > 0:
            checks_passed.append(f"IRC catalog has {len(irc_data)} cluster entries")
        elif isinstance(irc_data, list) and len(irc_data) > 0:
            checks_passed.append(f"IRC catalog has {len(irc_data)} files")
    else:
        errors.append("No IRC catalog found in output")

    # Step 11: Overall completeness check
    n_checks = len(checks_passed) + len(errors)
    n_passed = len(checks_passed)
    completeness = n_passed / max(n_checks, 1) * 100

    # Require at least 70% of checks to pass
    if len(errors) > 3:
        return (False, f"Evaluation failed with {len(errors)} error(s) ({completeness:.0f}% checks passed). "
                f"Errors: {'; '.join(errors)}. "
                f"Passed: {'; '.join(checks_passed[:5])}...")
    elif errors:
        # Minor errors - still pass if core functionality is there
        if len(checks_passed) >= 8:
            return (True, f"Evaluation passed with minor issues ({len(errors)} warning(s)). "
                    f"Checks passed: {'; '.join(checks_passed)}. "
                    f"Warnings: {'; '.join(errors)}")
        else:
            return (False, f"Evaluation failed: {'; '.join(errors)}. "
                    f"Only {len(checks_passed)} checks passed.")
    else:
        return (True, f"All {len(checks_passed)} evaluation checks passed: "
                f"{'; '.join(checks_passed)}")


